#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Sets the GitHub Actions secrets that .github/workflows/build.yml and
# update-homebrew-tap.yml read. Values go straight to GitHub, never into .env.

TOTAL_STAGES=4
cd "$(dirname "$0")/.."
REPO="yannickpulver/print-lab"
TAP="yannickpulver/homebrew-tap"

banner "Print Lab — release secrets for $REPO"

# ── 1 · Sparkle key ───────────────────────────────────────────────────────
stage "Sparkle update key"
say "Release builds sign the update feed with the Sparkle key in your login keychain."
note "macOS may ask to allow keychain access for generate_keys — allow it."
GENERATE_KEYS=$(find .build ~/Library/Developer/Xcode/DerivedData -path "*artifacts/sparkle/Sparkle/bin/generate_keys" -type f 2>/dev/null | head -1 || true)
if [[ -z "$GENERATE_KEYS" ]]; then
  say "Fetching Sparkle's tools first (tuist generate + package resolve)…"
  tuist generate --no-open >/dev/null
  xcodebuild -resolvePackageDependencies -workspace PrintLab.xcworkspace -scheme PrintLab -derivedDataPath .build/dd >/dev/null
  GENERATE_KEYS=".build/dd/SourcePackages/artifacts/sparkle/Sparkle/bin/generate_keys"
fi
EXPECTED_KEY=$(sed -nE 's/.*"SUPublicEDKey": "([^"]+)".*/\1/p' Project.swift)
KEYCHAIN_KEY=$("$GENERATE_KEYS" -p)
if [[ "$KEYCHAIN_KEY" != "$EXPECTED_KEY" ]]; then
  warn "The keychain key ($KEYCHAIN_KEY) does not match SUPublicEDKey in Project.swift ($EXPECTED_KEY)."
  warn "Updates signed with it would be rejected. Fix Project.swift first, then re-run."
  exit 1
fi
KEY_FILE=$(mktemp)
trap 'rm -f "$KEY_FILE"' EXIT
rm -f "$KEY_FILE"   # generate_keys -x refuses to overwrite
"$GENERATE_KEYS" -x "$KEY_FILE" >/dev/null
set_secret SPARKLE_PRIVATE_KEY "$(cat "$KEY_FILE")"
rm -f "$KEY_FILE"
pause

# ── 2 · Developer ID certificate ─────────────────────────────────────────
stage "Developer ID certificate"
say "CI signs the app with your Developer ID. Export it once as a .p12 file."
open -a "Keychain Access" 2>/dev/null || warn "open Keychain Access yourself"
step "Keychain Access → login → My Certificates."
step "Right-click 'Developer ID Application: Yannick Pulver (337L47P9N7)' → Export…"
step "Format 'Personal Information Exchange (.p12)', save it, choose a password."
P12_PATH=""
while true; do
  ask P12_PATH "Path to the .p12 file (drag it into this window):"
  P12_PATH="${P12_PATH%\"}"; P12_PATH="${P12_PATH#\"}"; P12_PATH="${P12_PATH%\'}"; P12_PATH="${P12_PATH#\'}"
  P12_PATH="${P12_PATH/#\~/$HOME}"; P12_PATH="${P12_PATH%% }"
  [[ -f "$P12_PATH" ]] && break
  warn "No file at '$P12_PATH' — try again."
done
while true; do
  ask_secret P12_PASSWORD "Password you chose for the .p12:"
  # OpenSSL 3 needs -legacy for older Keychain exports; LibreSSL has no such flag.
  SUBJECT=$( { P12_PASSWORD="$P12_PASSWORD" openssl pkcs12 -in "$P12_PATH" -nokeys -passin env:P12_PASSWORD 2>/dev/null \
      || P12_PASSWORD="$P12_PASSWORD" openssl pkcs12 -legacy -in "$P12_PATH" -nokeys -passin env:P12_PASSWORD 2>/dev/null; } \
    | openssl x509 -noout -subject 2>/dev/null || true)
  [[ "$SUBJECT" == *"Developer ID Application"* ]] && break
  warn "Wrong password, or the file holds no Developer ID Application certificate — try again."
done
TEAM_ID=$(sed -nE 's/.*OU ?= ?([A-Z0-9]{10}).*/\1/p' <<<"$SUBJECT")
note "Certificate: ${SUBJECT#subject=}"
set_secret APPLE_CERTIFICATE_BASE64 "$(base64 -i "$P12_PATH")"
set_secret APPLE_CERTIFICATE_PASSWORD "$P12_PASSWORD"
[[ -n "$TEAM_ID" ]] && set_secret APPLE_TEAM_ID "$TEAM_ID"
if confirm "Delete the exported .p12 now (it holds your private key)?"; then
  rm -f "$P12_PATH" && note "deleted $P12_PATH"
fi
pause

# ── 3 · Notarization login ───────────────────────────────────────────────
stage "Apple notarization login"
say "CI sends each release to Apple for notarization with an app-specific password."
open_url "https://account.apple.com/account/manage"
step "Sign-In and Security → App-Specific Passwords → '+'."
step "Name it 'print-lab notarization', create it, copy the password."
while true; do
  ask APPLE_ID "Apple ID (email of your developer account):"
  ask_secret APPLE_APP_PASSWORD "App-specific password (xxxx-xxxx-xxxx-xxxx):"
  note "Checking the login with Apple…"
  if xcrun notarytool history --apple-id "$APPLE_ID" --team-id "${TEAM_ID:-337L47P9N7}" \
       --password "$APPLE_APP_PASSWORD" >/dev/null 2>&1; then
    printf '  %s✓ Apple accepted the login%s\n' "$GREEN" "$RESET"
    break
  fi
  warn "Apple rejected this Apple ID / password — try again."
done
set_secret APPLE_ID "$APPLE_ID"
set_secret APPLE_APP_PASSWORD "$APPLE_APP_PASSWORD"
pause

# ── 4 · Homebrew tap token ───────────────────────────────────────────────
stage "Homebrew tap token"
say "After a release, CI writes Casks/print-lab.rb into $TAP."
# The same token serves all apps in the tap; it lives in 1Password.
OP_REF="op://Personal/Homebrew Tap Github PAT Token/password"
HOMEBREW_TAP_TOKEN=""
if command -v op >/dev/null 2>&1 && confirm "Use the shared tap token from 1Password?"; then
  HOMEBREW_TAP_TOKEN=$(op read "$OP_REF" 2>/dev/null || true)
  [[ -z "$HOMEBREW_TAP_TOKEN" ]] && warn "Could not read $OP_REF — create a new token instead."
fi
if [[ -z "$HOMEBREW_TAP_TOKEN" ]]; then
  open_url "https://github.com/settings/personal-access-tokens/new"
  step "Token name 'homebrew tap', expiration as you like."
  step "Repository access → Only select repositories → $TAP."
  step "Permissions → Repository → Contents: Read and write. Generate, copy."
fi
while true; do
  [[ -z "$HOMEBREW_TAP_TOKEN" ]] && ask_secret HOMEBREW_TAP_TOKEN "Paste the token (github_pat_…):"
  # GitHub reports the owner's rights here, not the token's: this proves the token reaches the tap.
  if GH_TOKEN="$HOMEBREW_TAP_TOKEN" gh api "repos/$TAP" --jq .full_name >/dev/null 2>&1; then
    printf '  %s✓ token reaches %s%s\n' "$GREEN" "$TAP" "$RESET"
    note "Make sure Contents is 'Read and write' — the first release run shows if it is."
    break
  fi
  warn "This token cannot see $TAP — check 'Only select repositories'."
  HOMEBREW_TAP_TOKEN=""
done
set_secret HOMEBREW_TAP_TOKEN "$HOMEBREW_TAP_TOKEN"

finish
say "Next: push to main with a new VERSION to build the first release."
